class Bloom {
  final List<bool> _bits;
  final int _k;
  Bloom(int size, this._k) : _bits = List.filled(size, false);
  void add(String s) { for (var i = 0; i < _k; i++) { _bits[_hash(s, i) % _bits.length] = true; } }
  bool mightContain(String s) => List.generate(_k, (i) => _bits[_hash(s, i) % _bits.length]).every((b) => b);
}

export function allow(key: string, now = Date.now()): boolean {
  const w = windows.get(key) ?? [];
  const fresh = w.filter((t) => now - t < WINDOW_MS);
  if (fresh.length >= LIMIT) return false;
  fresh.push(now);
  windows.set(key, fresh);
  return true;
}
